"""Human-readable exact-key ledger and complete non-FPS benchmark tables."""
def report(stats,bench,focused):
 n=lambda x:f'{x:,}'.replace(',',' ')
 p=stats['after_percent'];bar='█'*round(p*30/100)+'░'*(30-round(p*30/100))
 out=['# Перевод NPC — 0.15.100','',f'`{bar}` **{p:.2f}%** точных ключей публичной очереди. Полоса округлена.','','| Показатель | До | После |','| --- | ---: | ---: |','| Точные ключи | 10 009 · 61,62% | 10 391 · 63,97% |','| Без подтверждённого ключа | 6 235 | 5 853 · 36,03% |','| Всего в зафиксированной очереди | 16 244 | 16 244 |','','Это не процент готовности всей игры. В очереди есть исторические, тестовые, нейтральные, редакторские строки и переменные. Закрытые скрипты сервера не выгружены; часть динамических переводов работает без отдельного точного ключа.','','## Этот проход','','382 новые реплики / 54 обозначения НПС, включая семь телефонных реплик. Восемь точных групп ответов / девять подписей / восемь опубликованных оформлений. Сверены 55 текущих публичных ревизий — все совпали с зафиксированными.','','| Говорящий | Новых ключей |','| --- | ---: |']
 out += [f'| {name} | {count} |' for name,count in stats['new_by_speaker'].items()]
 out+=['| Всего | 382 |','','405 выбранных строк: 382 новые, 6 прежних, 14 с переменными, 1 проблема извлечения, 2 нейтральные. Архив Dante и другие ограничения отмечены отдельно. Требуемая английская фраза для задания Eleanor намеренно сохранена.','','[Контекстная вычитка](NPC_0.15.100_REVIEW_NOTES.md) · [Все говорящие и остаток](NPC_ALL_SPEAKERS_0.15.100_RU.md).','','## Проверки','',f'169 групп заново проверены на окончательном JAR, плюс 15 тестов извлечения. Новые реплики: {n(stats["new_fixture_assertions"])} проверок; кнопки: {n(stats["new_choice_fixture_assertions"])}. Проверяется стиль каждого символа: цвета, курсив, свежие клики и подсказки, числа, дробление компонентов, счётчики, время, пользовательские замены, подписанный/пользовательский чат.','','На выборке из 11 247 строк все 382 новых перевода совпали с ожидаемыми в обычном и опубликованном цветном виде. Остальные 10 865 результатов не изменились. 72 прежних пробела цветного распознавания не объявлены исправленными.','','## Оптимизация','','Сравнение 0.15.99 → 0.15.100. Новые ключи загружаются в существующий словарь при запуске; число обработчиков и покадровых проходов не увеличено. Исполняемые инструкции вне стартовых таблиц совпали; остальные классы, включая HUD/F3, побайтно те же. Расход памяти при загрузке словаря увеличивается — нулевое влияние не обещается.','','Используемая пользователем 0.15.96 и отключённая 0.15.92 не изменены. Игра не перезапускалась, JAR автоматически не установлен.','','Ниже изолированные измерения, не FPS, GPU, время кадра или 0,1% lows. По четыре отдельные JVM в порядке 99 → 100 → 100 → 99, оба порядка и все раунды сохранены. Время относится к сообщению/операции, не ко всему кадру.']
 def table(family,title):
  out.extend(['',f'### {title}','','| Сценарий | Одинаковая полезная работа | До → после, мкс | Изменение, оба порядка | Байты до → после |','| --- | --- | ---: | ---: | ---: |'])
  for r in family['summary']:
   times=' / '.join(f'{o["before_ns"]/1000:.3f} → {o["after_ns"]/1000:.3f}' for o in r['orders']);change=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);memory=' / '.join(f'{o["before_bytes"]:.0f} → {o["after_bytes"]:.0f}' for o in r['orders']);out.append(f'| {r["mode"]} | {"Да" if r["equal_useful_output"] else "Нет: новый перевод"} | {times} | {change} | {memory} |')
 for name,f in bench['families'].items():table(f,name)
 out+=['','В двух new_* сценариях только новая версия переводит текст. Это разная полезная работа: проценты этих сценариев не являются регрессией одинакового пути.','','Контрольный длинный повтор: ещё четыре JVM, шесть прежних сценариев, увеличенный прогрев. Он дополняет, а не заменяет первые результаты.']
 table(focused,'Контрольный повтор')
 changes=[o['wall_change_percent'] for r in focused['summary'] for o in r['orders']]
 out+=['',f'Диапазон контрольного повтора: {min(changes):+.1f}%…{max(changes):+.1f}%. Все результаты сохранены. Это не доказывает отсутствие микролагов в игре.','','## Остаток','','5 853 строки без подтверждённого точного ключа. Продолжается работа над NPC, динамическими обращениями, меню, историческими условиями и качеством извлечения. Все NPC и весь Абифон не объявляются завершёнными.','',f'SHA-256 JAR: `{stats["runtime_jar_sha256"]}`.']
 return '\n'.join(out)+'\n'
